// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Status code.
*
* ## Notes
*
* The status code indicates the following conditions:
*
* -   if equal to zero, then the reduction was successful.
* -   if less than zero, then the value of the `-StatusCode`th argument had an illegal value.
*/
type StatusCode = number;

/**
* Interface describing `dgebrd`.
*/
interface Routine {
	/**
	* Reduces a general real `M-by-N` matrix `A` to upper or lower bidiagonal form `B` by an orthogonal transformation `Q**T * A * P = B`.
	*
	* -   If `M >= N`,
	*
	*     -   `B` is upper bi-diagonal form.
	*     -   The diagonal and the first superdiagonal are overwritten with the upper bi-diagonal matrix `B`.
	*     -   Elements below the diagonal, with the array `TAUQ`, represent the orthogonal matrix `Q` as a product of elementary reflectors.
	*     -   Elements above the first super-diagonal, with the array `TAUP`, represent the orthogonal matrix `P` as a product of elementary reflectors.
	*
	* -   If `M < N`,
	*
	*     -   `B` is lower bi-diagonal form.
	*     -   The diagonal and the first sub-diagonal are overwritten with the lower bi-diagonal matrix `B`.
	*     -   Elements below the first sub-diagonal, with the array `TAUQ`, represent the orthogonal matrix `Q` as a product of elementary reflectors.
	*     -   Elements on and above the diagonal, with the array `TAUP`, represent the orthogonal matrix `P` as a product of elementary reflectors.
	*
	* @param order - storage layout
	* @param M - number of rows in `A`
	* @param N - number of columns in `A`
	* @param A - input matrix
	* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
	* @param D - the diagonal elements of the bidiagonal matrix `B`
	* @param E - the off-diagonal elements of the bidiagonal matrix `B`
	* @param TAUQ - the scalar factors of the elementary reflectors that represent the orthogonal matrix `Q`
	* @param TAUP - the scalar factors of the elementary reflectors that represent the orthogonal matrix `P`
	* @param WORK - workspace array
	* @param LWORK - length of `WORK`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 4.0, -1.0, 2.5, 7.0, 8.5, -2.0 ] );
	* var D = new Float64Array( [ 0.0, 0.0 ] );
	* var E = new Float64Array( [ 0.0 ] );
	* var TAUQ = new Float64Array( [ 0.0, 0.0 ] );
	* var TAUP = new Float64Array( [ 0.0, 0.0 ] );
	* var WORK = new Float64Array( 100 );
	*
	* dgebrd( 'column-major', 3, 2, A, 3, D, E, TAUQ, TAUP, WORK, 100 );
	* // A => <Float64Array>[ ~-4.822, ~-0.113, ~0.283, ~-3.007, ~-10.78, ~-0.237 ]
	* // D => <Float64Array>[ ~-4.822, ~-10.78 ]
	* // E => <Float64Array>[ ~-3.007 ]
	* // TAUQ => <Float64Array>[ ~1.83, ~1.894 ]
	* // TAUP => <Float64Array>[ 0.0, 0.0 ]
	* // WORK[ 0 ] => 3.0
	*/
	( order: Layout, M: number, N: number, A: Float64Array, LDA: number, D: Float64Array, E: Float64Array, TAUQ: Float64Array, TAUP: Float64Array, WORK: Float64Array, LWORK: number ): StatusCode;

	/**
	* Reduces a general real `M-by-N` matrix `A` to upper or lower bidiagonal form `B` by an orthogonal transformation `Q**T * A * P = B` using alternative indexing semantics.
	*
	* -   If `M >= N`,
	*
	*     -   `B` is upper bi-diagonal form.
	*     -   The diagonal and the first superdiagonal are overwritten with the upper bi-diagonal matrix `B`.
	*     -   Elements below the diagonal, with the array `TAUQ`, represent the orthogonal matrix `Q` as a product of elementary reflectors.
	*     -   Elements above the first super-diagonal, with the array `TAUP`, represent the orthogonal matrix `P` as a product of elementary reflectors.
	*
	* -   If `M < N`,
	*
	*     -   `B` is lower bi-diagonal form.
	*     -   The diagonal and the first sub-diagonal are overwritten with the lower bi-diagonal matrix `B`.
	*     -   Elements below the first sub-diagonal, with the array `TAUQ`, represent the orthogonal matrix `Q` as a product of elementary reflectors.
	*     -   Elements on and above the diagonal, with the array `TAUP`, represent the orthogonal matrix `P` as a product of elementary reflectors.
	*
	* @param M - number of rows in `A`
	* @param N - number of columns in `A`
	* @param A - input matrix
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index for `A`
	* @param D - the diagonal elements of the bidiagonal matrix `B`
	* @param strideD - stride length for `D`
	* @param offsetD - starting index for `D`
	* @param E - the off-diagonal elements of the bidiagonal matrix `B`
	* @param strideE - stride length for `E`
	* @param offsetE - starting index for `E`
	* @param TAUQ - the scalar factors of the elementary reflectors that represent the orthogonal matrix `Q`
	* @param strideTAUQ - stride length for `TAUQ`
	* @param offsetTAUQ - starting index for `TAUQ`
	* @param TAUP - the scalar factors of the elementary reflectors that represent the orthogonal matrix `P`
	* @param strideTAUP - stride length for `TAUP`
	* @param offsetTAUP - starting index for `TAUP`
	* @param WORK - workspace array
	* @param strideWORK - stride length for `WORK`
	* @param offsetWORK - starting index for `WORK`
	* @param LWORK - length of `WORK`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 4.0, -1.0, 2.5, 7.0, 8.5, -2.0 ] );
	* var D = new Float64Array( [ 0.0, 0.0 ] );
	* var E = new Float64Array( [ 0.0 ] );
	* var TAUQ = new Float64Array( [ 0.0, 0.0 ] );
	* var TAUP = new Float64Array( [ 0.0, 0.0 ] );
	* var WORK = new Float64Array( 100 );
	*
	* dgebrd.ndarray( 3, 2, A, 1, 3, 0, D, 1, 0, E, 1, 0, TAUQ, 1, 0, TAUP, 1, 0, WORK, 1, 0, 100 );
	* // A => <Float64Array>[ ~-4.822, ~-0.113, ~0.283, ~-3.007, ~-10.78, ~-0.237 ]
	* // D => <Float64Array>[ ~-4.822, ~-10.78 ]
	* // E => <Float64Array>[ ~-3.007 ]
	* // TAUQ => <Float64Array>[ ~1.83, ~1.894 ]
	* // TAUP => <Float64Array>[ 0.0, 0.0 ]
	* // WORK[ 0 ] => 3.0
	*/
	ndarray( M: number, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, D: Float64Array, strideD: number, offsetD: number, E: Float64Array, strideE: number, offsetE: number, TAUQ: Float64Array, strideTAUQ: number, offsetTAUQ: number, TAUP: Float64Array, strideTAUP: number, offsetTAUP: number, WORK: Float64Array, strideWORK: number, offsetWORK: number, LWORK: number ): StatusCode;
}

/**
* LAPACK routine to reduce a general real `M-by-N` matrix `A` to upper or lower bidiagonal form `B` by an orthogonal transformation `Q**T * A * P = B`.
*
* ## Notes
*
* -   If `M >= N`,
*
*     -   `B` is upper bi-diagonal form.
*     -   The diagonal and the first superdiagonal are overwritten with the upper bi-diagonal matrix `B`.
*     -   Elements below the diagonal, with the array `TAUQ`, represent the orthogonal matrix `Q` as a product of elementary reflectors.
*     -   Elements above the first super-diagonal, with the array `TAUP`, represent the orthogonal matrix `P` as a product of elementary reflectors.
*
* -   If `M < N`,
*
*     -   `B` is lower bi-diagonal form.
*     -   The diagonal and the first sub-diagonal are overwritten with the lower bi-diagonal matrix `B`.
*     -   Elements below the first sub-diagonal, with the array `TAUQ`, represent the orthogonal matrix `Q` as a product of elementary reflectors.
*     -   Elements on and above the diagonal, with the array `TAUP`, represent the orthogonal matrix `P` as a product of elementary reflectors.
*
* @param order - storage layout
* @param M - number of rows in `A`
* @param N - number of columns in `A`
* @param A - input matrix
* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param D - the diagonal elements of the bidiagonal matrix `B`
* @param E - the off-diagonal elements of the bidiagonal matrix `B`
* @param TAUQ - the scalar factors of the elementary reflectors that represent the orthogonal matrix `Q`
* @param TAUP - the scalar factors of the elementary reflectors that represent the orthogonal matrix `P`
* @param WORK - workspace array
* @param LWORK - length of `WORK`
* @returns status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 4.0, -1.0, 2.5, 7.0, 8.5, -2.0 ] );
* var D = new Float64Array( [ 0.0, 0.0 ] );
* var E = new Float64Array( [ 0.0 ] );
* var TAUQ = new Float64Array( [ 0.0, 0.0 ] );
* var TAUP = new Float64Array( [ 0.0, 0.0 ] );
* var WORK = new Float64Array( 100 );
*
* dgebrd( 'column-major', 3, 2, A, 3, D, E, TAUQ, TAUP, WORK, 100 );
* // A => <Float64Array>[ ~-4.822, ~-0.113, ~0.283, ~-3.007, ~-10.78, ~-0.237 ]
* // D => <Float64Array>[ ~-4.822, ~-10.78 ]
* // E => <Float64Array>[ ~-3.007 ]
* // TAUQ => <Float64Array>[ ~1.83, ~1.894 ]
* // TAUP => <Float64Array>[ 0.0, 0.0 ]
* // WORK[ 0 ] => 3.0
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 4.0, -1.0, 2.5, 7.0, 8.5, -2.0 ] );
* var D = new Float64Array( [ 0.0, 0.0 ] );
* var E = new Float64Array( [ 0.0 ] );
* var TAUQ = new Float64Array( [ 0.0, 0.0 ] );
* var TAUP = new Float64Array( [ 0.0, 0.0 ] );
* var WORK = new Float64Array( 100 );
*
* dgebrd.ndarray( 3, 2, A, 1, 3, 0, D, 1, 0, E, 1, 0, TAUQ, 1, 0, TAUP, 1, 0, WORK, 1, 0, 100 );
* // A => <Float64Array>[ ~-4.822, ~-0.113, ~0.283, ~-3.007, ~-10.78, ~-0.237 ]
* // D => <Float64Array>[ ~-4.822, ~-10.78 ]
* // E => <Float64Array>[ ~-3.007 ]
* // TAUQ => <Float64Array>[ ~1.83, ~1.894 ]
* // TAUP => <Float64Array>[ 0.0, 0.0 ]
* // WORK[ 0 ] => 3.0
*/
declare var dgebrd: Routine;


// EXPORTS //

export = dgebrd;
